// Read the high-water-mark from workflow static data.
// On the first run, fall back to PG_SYNC_HWM_INITIAL env var.
// Output one item with the current HWM for the Postgres node to consume.

const data = $getWorkflowStaticData('global');
let hwm = data.lastSyncedAt;
if (!hwm) {
  const seed = $env.PG_SYNC_HWM_INITIAL;
  if (!seed) throw new Error('PG_SYNC_HWM_INITIAL env var is required for the first run (ISO-8601 timestamp)');
  // Validate seed is a parseable ISO date
  const seedDate = new Date(seed);
  if (isNaN(seedDate.getTime())) throw new Error('PG_SYNC_HWM_INITIAL is not a valid ISO-8601 date: ' + seed);
  hwm = seedDate.toISOString();
}

return [{ json: { hwm, runStartedAt: new Date().toISOString() } }];

// Per-key sliding-window rate limit on the Sheets API call, opt-in.
// Default 60 ops / 5 min, scoped workflow-wide.

if ($env.RATE_LIMIT_ENABLED !== '1') {
  return $input.all();
}

const LIMIT = 60;
const WINDOW_MS = 5 * 60 * 1000;
const MAX_KEYS = 5000;

const data = $getWorkflowStaticData('global');
data.rateBuckets = data.rateBuckets || {};
const buckets = data.rateBuckets;
const now = Date.now();

for (const k of Object.keys(buckets)) {
  buckets[k] = (buckets[k] || []).filter(t => now - t < WINDOW_MS);
  if (buckets[k].length === 0) delete buckets[k];
}
if (Object.keys(buckets).length > MAX_KEYS) {
  const oldest = Object.entries(buckets).sort((a, b) => (a[1][0] || 0) - (b[1][0] || 0)).slice(0, 100);
  for (const [k] of oldest) delete buckets[k];
}

const key = 'sheets-write';
const hits = buckets[key] || [];
if (hits.length >= LIMIT) {
  throw new Error('RATE_LIMIT_EXCEEDED: ' + LIMIT + ' Sheets writes per ' + Math.round(WINDOW_MS / 60000) + ' minutes reached');
}
buckets[key] = [...hits, now];

return $input.all();

// 24-hour idempotency window on row primary key, opt-in.
// Drops rows already seen within the window. Reads `id` (or PG_SYNC_DEDUP_KEY env) from each row.

const crypto = require('crypto');

if ($env.IDEMPOTENCY_ENABLED !== '1') {
  return $input.all();
}

const WINDOW_MS = 24 * 60 * 60 * 1000;
const MAX_KEYS = 50000;
const dedupKeyField = $env.PG_SYNC_DEDUP_KEY || 'id';

const data = $getWorkflowStaticData('global');
data.seenRows = data.seenRows || {};
const seen = data.seenRows;
const now = Date.now();

for (const k of Object.keys(seen)) {
  if (now - seen[k] > WINDOW_MS) delete seen[k];
}
if (Object.keys(seen).length > MAX_KEYS) {
  const oldest = Object.entries(seen).sort((a, b) => a[1] - b[1]).slice(0, 5000);
  for (const [k] of oldest) delete seen[k];
}

const out = [];
for (const item of $input.all()) {
  const j = item.json || {};
  const pkRaw = j[dedupKeyField];
  if (pkRaw == null) { out.push(item); continue; } // no PK -> let it through, do not drop
  const pkStr = String(pkRaw);
  const hashed = crypto.createHash('sha256').update(pkStr, 'utf8').digest('hex').slice(0, 32);
  if (seen[hashed]) continue; // dedup hit
  seen[hashed] = now;
  out.push(item);
}
return out;

// Redis variant for clustered n8n:
// const result = await redis.set('pgsheets-idem:' + hashed, '1', 'EX', 86400, 'NX');
// if (result === null) skip;

// Hard cap defense before we hand the rows to Sheets.
// MAX_ROWS_PER_RUN env (default 5000). If exceeded, slice and warn.

const MAX_ROWS = parseInt($env.MAX_ROWS_PER_RUN || '5000', 10);
const items = $input.all();
if (items.length === 0) {
  return [{ json: { skipped: true, reason: 'no-new-rows' } }];
}
if (items.length > MAX_ROWS) {
  // Take the first MAX_ROWS, the rest will be picked up next run via the HWM.
  return items.slice(0, MAX_ROWS);
}
return items;

// Project each Postgres row into a Sheets row-shape. Order matters for Sheets append.
// PG_SYNC_COLUMN_ORDER env defines the column projection. Example: 'id,email,created_at,updated_at'.
// If unset, falls back to the keys of the first row (ordering not guaranteed across rows).

const items = $input.all();
if (items.length === 0 || (items[0].json && items[0].json.skipped)) {
  return items;
}

const order = ($env.PG_SYNC_COLUMN_ORDER || '').split(',').map(s => s.trim()).filter(Boolean);
const keys = order.length > 0 ? order : Object.keys(items[0].json || {});

const values = items.map(item => {
  const row = item.json || {};
  return keys.map(k => {
    const v = row[k];
    if (v == null) return '';
    if (v instanceof Date) return v.toISOString();
    if (typeof v === 'object') return JSON.stringify(v);
    return String(v);
  });
});

return [{ json: { values, columnOrder: keys, rowCount: values.length } }];

// Update the HWM only after a successful Sheets append.
// New HWM = max(updated_at, created_at, ...) across the rows we just synced.
// PG_SYNC_HWM_FIELD env names the timestamp field. Default 'updated_at'.

const hwmField = $env.PG_SYNC_HWM_FIELD || 'updated_at';
const pgRows = $('Cap MAX_ROWS_PER_RUN').all();
if (pgRows.length === 0 || (pgRows[0].json && pgRows[0].json.skipped)) {
  return [{ json: { hwmUnchanged: true } }];
}

let maxTs = null;
for (const item of pgRows) {
  const v = (item.json || {})[hwmField];
  if (v == null) continue;
  const d = new Date(v);
  if (isNaN(d.getTime())) continue;
  if (!maxTs || d > maxTs) maxTs = d;
}
if (!maxTs) {
  return [{ json: { hwmUnchanged: true, reason: 'no-' + hwmField + '-field-on-rows' } }];
}

const data = $getWorkflowStaticData('global');
data.lastSyncedAt = maxTs.toISOString();

return [{ json: { newHwm: data.lastSyncedAt, rowsSynced: pgRows.length } }];

// Fallback when Postgres OR Sheets fails. Build a structured error log
// and post a Slack alert if SLACK_OPS_WEBHOOK is set.

const input = $input.first();
const raw = input.json || {};
const errorRaw = raw.error || raw;
const isHttpOrPgError = !!(errorRaw && (errorRaw.message || errorRaw.code));
const errorMessage = isHttpOrPgError ? (errorRaw.message || 'Sync error') : 'Unknown error: ' + JSON.stringify(errorRaw).slice(0, 200);

// Identify which stage failed.
let stage = 'unknown';
try { if ($('Postgres Query').first()) stage = 'after-postgres'; } catch (e) {}
try { if ($('Append to Sheets').first()) stage = 'after-sheets'; } catch (e) {}

return [{
  json: {
    syncError: { message: errorMessage, stage, raw: errorRaw },
    runStartedAt: ($('Read HWM').first() && $('Read HWM').first().json && $('Read HWM').first().json.runStartedAt) || null,
  },
}];
